<script setup lang="ts">import{Head,Link,router}from'@inertiajs/vue3';import ErpLayout from '@/Layouts/ErpLayout.vue';import TreasuryLifecycleActions from '@/Components/Accounting/TreasuryLifecycleActions.vue';import type{TreasuryAdjustmentDetail}from'@/Types/treasury';defineOptions({layout:ErpLayout});const props=defineProps<{document:TreasuryAdjustmentDetail}>();const money=(v:string):string=>new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:6}).format(Number(v));const remove=():void=>{if(window.confirm('Delete this Treasury Adjustment draft?'))router.delete(route('treasury-adjustments.destroy',props.document.id));};</script>
<template><Head :title="document.adjustment_number??`Treasury Adjustment #${document.id}`"/><div class="space-y-6"><div class="flex justify-between gap-4"><div><Link :href="route('treasury-adjustments.index')" class="text-sm text-brand-600">Treasury Adjustments</Link><div class="mt-2 flex items-center gap-3"><h1 class="text-2xl font-semibold">{{document.adjustment_number??`Draft #${document.id}`}}</h1><span class="rounded-full bg-gray-100 px-2.5 py-1 text-xs dark:bg-gray-800">{{document.status_label}}</span></div><p class="mt-1 text-sm text-gray-500">{{document.adjustment_type_label}} · Revision {{document.revision}}</p></div><div class="flex gap-2"><Link v-if="document.can.update" :href="route('treasury-adjustments.edit',document.id)" class="rounded-lg border px-4 py-2 text-sm dark:border-gray-700">Edit</Link><button v-if="document.can.delete" class="rounded-lg border border-error-300 px-4 py-2 text-sm text-error-600" @click="remove">Delete</button></div></div><div class="rounded-2xl border bg-white p-5 dark:border-gray-800 dark:bg-gray-900"><TreasuryLifecycleActions :document-id="document.id" route-prefix="treasury-adjustments" :status="document.status" :can="document.can"/></div><div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><div v-for="x in [['Adjustment Date',document.adjustment_date],['Posting Date',document.posting_date],['Amount',`${document.currency_code} ${money(document.amount)}`],['Base Amount',money(document.base_amount)]]" :key="String(x[0])" class="rounded-2xl border bg-white p-5 dark:border-gray-800 dark:bg-gray-900"><p class="text-xs uppercase text-gray-500">{{x[0]}}</p><p class="mt-2 font-semibold">{{x[1]}}</p></div></div><div class="grid gap-6 lg:grid-cols-2"><div class="rounded-2xl border bg-white p-6 dark:border-gray-800 dark:bg-gray-900"><h2 class="text-lg font-semibold">Accounting Direction</h2><dl class="mt-5 grid grid-cols-2 gap-4 text-sm"><dt class="text-gray-500">Branch</dt><dd>{{document.branch?.code}} — {{document.branch?.name}}</dd><dt class="text-gray-500">Bank account</dt><dd>{{document.bank_account?.code}} — {{document.bank_account?.name}}</dd><dt class="text-gray-500">Offset account</dt><dd>{{document.offset_account?.code}} — {{document.offset_account?.name}}</dd><dt class="text-gray-500">Reference</dt><dd>{{document.reference??'—'}}</dd></dl></div><div class="rounded-2xl border bg-white p-6 dark:border-gray-800 dark:bg-gray-900"><h2 class="text-lg font-semibold">Description</h2><p class="mt-4 whitespace-pre-line text-sm">{{document.description}}</p><div v-if="document.statement_line" class="mt-5 rounded-xl bg-gray-50 p-4 text-sm dark:bg-gray-800"><b>Statement line #{{document.statement_line.line_number}}</b><p>{{document.statement_line.transaction_date}} · {{document.statement_line.bank_reference??'—'}}</p><p>{{document.statement_line.description}}</p></div></div></div><div class="rounded-2xl border bg-white p-6 dark:border-gray-800 dark:bg-gray-900"><h2 class="text-lg font-semibold">Audit and General Ledger</h2><dl class="mt-4 grid gap-4 sm:grid-cols-2 lg:grid-cols-4 text-sm"><div><dt class="text-gray-500">Created by</dt><dd>{{document.created_by?.name??'—'}}</dd></div><div><dt class="text-gray-500">Posted by</dt><dd>{{document.posted_by?.name??'—'}}</dd></div><div><dt class="text-gray-500">Posting reference</dt><dd class="break-all">{{document.accounting_posting_reference??'—'}}</dd></div><div><dt class="text-gray-500">Reversal reference</dt><dd class="break-all">{{document.accounting_reversal_reference??'—'}}</dd></div></dl></div><div v-if="document.cancellation_reason||document.reversal_reason" class="rounded-xl border border-error-200 bg-error-50 p-4 text-sm text-error-700">{{document.reversal_reason??document.cancellation_reason}}</div></div></template>
